SELECT n.nspname AS schema_name, o.relname AS object_name, a.attname AS column_name, COALESCE(d.description, '') AS text FROM pg_class o JOIN pg_namespace n ON n.oid = o.relnamespace JOIN pg_attribute a ON a.attrelid = o.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_description d ON d.objoid = o.oid AND d.classoid = 'pg_class'::regclass AND d.objsubid = a.attnum WHERE d.description IS NOT NULL ORDER BY n.nspname, o.relname, a.attnum;
